import type { Sink, Source } from "./Core";
/**
 * A callbag sink that listens to a callbag source
 * and invokes the callbacks passed in.
 *
 * Adapted from https://github.com/zebulonj/callbag-subscribe
 *
 * @param source The callbag source.
 * @param listener A object with callbacks, a single data callback, or
 *     a callbag sink to pipe emits to.
 * @returns A function used to cancel the subscription.
 *
 * @internal
 */
export declare const subscribe: <T, E>(source: Source<T, E>, listener?: {
    next?: ((data: T) => void) | undefined;
    error?: ((err: E) => void) | undefined;
    complete?: (() => void) | undefined;
} | {
    sink: Sink<T, E>;
} | ((data: T) => void)) => (() => void);
